/**
 * Returns the most recent profile edits for one employee, newest
first. Admin can read any employee's log; non-admin callers may
only read their own. Sensitive field values (bank account number,
SSN, signature) are masked at write time.

 * @summary Recent per-field profile change log
 */
export const GetEmployeeChangesParams = zod.object({
  id: zod.coerce.string(),
});

export const getEmployeeChangesQueryLimitDefault = 20;
export const getEmployeeChangesQueryLimitMax = 100;

export const GetEmployeeChangesQueryParams = zod.object({
  limit: zod.coerce
    .number()
    .min(1)
    .max(getEmployeeChangesQueryLimitMax)
    .default(getEmployeeChangesQueryLimitDefault),
});

export const GetEmployeeChangesResponse = zod.object({
  rows: zod.array(
    zod.object({
      id: zod.string(),
      employeeUserId: zod.string(),
      actorUserId: zod.string().nullish(),
      actorEmail: zod.string().nullish(),
      actorName: zod.string().nullish(),
      actorRole: zod.string().nullish(),
      source: zod.enum(["admin", "self"]),
      field: zod.string(),
      fieldLabel: zod.string().optional(),
      oldValue: zod.string().nullish(),
      newValue: zod.string().nullish(),
      changedAt: zod.coerce.date(),
    }),
  ),
});

/**
 * @summary List shifts
 */
export const GetShiftsQueryParams = zod.object({
  status: zod.enum(["upcoming", "active", "completed", "cancelled"]).optional(),
  employeeId: zod.coerce.string().optional(),
  from: zod.date().optional(),
  to: zod.date().optional(),
});

export const GetShiftsResponseItem = zod.object({
  id: zod.string(),
  title: zod.string(),
  siteId: zod.string().optional(),
  siteName: zod.string().optional(),
  clientName: zod.string().optional(),
  clientId: zod.string().optional(),
  location: zod.string().optional(),
  locationLat: zod.number().optional(),
  locationLng: zod.number().optional(),
  startTime: zod.coerce.date(),
  endTime: zod.coerce.date(),
  payRate: zod.number().optional().describe("What the officer earns per hour"),
  billRate: zod
    .number()
    .optional()
    .describe("What the client is billed per hour"),
  hourlyRate: zod.number().optional().describe("Legacy alias for payRate"),
  billableRate: zod.number().optional().describe("Legacy alias for billRate"),
  status: zod.enum(["upcoming", "active", "completed", "cancelled"]),
  shiftType: zod
    .enum(["standard", "ppo_detail"])
    .optional()
    .describe(
      "'standard' guard shift or 'ppo_detail' executive\/close-protection detail (unlocks the protection package)",
    ),
  requiredLicenseLevel: zod
    .union([zod.literal(1), zod.literal(2), zod.literal(3), zod.literal(4)])
    .describe(
      "Minimum license level required (1=support\/no licence, 2=unarmed, 3=armed, 4=PPO)",
    ),
  headcount: zod
    .number()
    .describe("Total number of officers needed for this shift"),
  isRepeat: zod.boolean(),
  repeatPattern: zod
    .enum(["daily", "weekly", "fortnightly", "monthly"])
    .optional(),
  notes: zod.string().optional(),
  assignments: zod
    .array(
      zod.object({
        id: zod.string(),
        shiftId: zod.string(),
        employeeId: zod.string(),
        employeeName: zod.string().optional(),
        status: zod
          .enum(["pending", "accepted", "declined", "pending_approval"])
          .describe(
            "Assignment state. `pending` = admin-invited, awaiting the officer's acceptance. `pending_approval` = officer self-claimed, awaiting an admin's approval (slot is held — counts toward headcount — but the officer is not yet confirmed). `accepted` = confirmed on the roster. `declined` = removed (the row is deleted, freeing the slot).",
          ),
        createdAt: zod.coerce.date(),
      }),
    )
    .optional(),
  distanceMilesFromHome: zod
    .number()
    .nullish()
    .describe(
      "Miles from the requesting employee's geocoded home address to the shift's site (haversine). Null when caller is admin\/dispatcher, when either the employee or the site has no coords on file, or when the shift has no site. Used by the mobile open-shifts list to sort nearest-first and to prompt confirmation on shifts 50+ miles away.",
    ),
  createdAt: zod.coerce.date(),
});
export const GetShiftsResponse = zod.array(GetShiftsResponseItem);

